// Validate settings and build the Actor input. Fails early (before any paid work) on bad settings.
const s = $('Podcast settings').first().json;
const feeds = String(s.feedUrls || '')
  .split(/[\n,]+/).map(x => x.trim()).filter(Boolean);
if (!feeds.length) throw new Error('Add at least one podcast RSS feed URL in "Podcast settings".');
const bad = feeds.filter(f => !/^https?:\/\//i.test(f));
if (bad.length) throw new Error('These feed entries are not http(s) URLs: ' + bad.join(', '));
if (!s.spreadsheetId || /YOUR_/i.test(s.spreadsheetId)) {
  throw new Error('Set spreadsheetId in "Podcast settings" (the long ID in your Google Sheet URL).');
}
const max = Math.max(1, Math.min(Number(s.maxTranscriptsPerRun) || 25, 500));
const actorInput = {
  feedUrls: feeds.slice(0, 100),
  maxEpisodesPerFeed: Math.max(1, Math.min(Number(s.maxEpisodesPerFeed) || 3, 50)),
  maxResults: max,
  onlyWithTranscripts: true,
  includeSegments: false,          // plain text only: keeps rows small enough for Sheets
  includeSpeakerLabels: true,
};
if (s.publishedSince) actorInput.publishedSince = String(s.publishedSince);
return [{ json: {
  actorInput,
  spreadsheetId: String(s.spreadsheetId).trim(),
  sheetName: String(s.sheetName || 'Transcripts'),
  maxCostPerRunUsd: Number(s.maxCostPerRunUsd) || 0.1,
} }];

// Compare fetched episodes with the GUIDs already in the sheet; keep only new ones.
const saved = new Set($input.all().map(i => String(i.json.guid || '').trim()).filter(Boolean));
const fetched = $('Fetch published transcripts').all().map(i => i.json)
  .filter(r => r && r.guid && r.hasTranscript && r.text);
const CELL_LIMIT = 45000; // Google Sheets allows 50,000 characters per cell
const now = new Date().toISOString();
const out = [];
for (const r of fetched) {
  const key = String(r.guid).trim();
  if (saved.has(key)) continue;
  saved.add(key); // also removes duplicates inside one run
  const text = String(r.text);
  out.push({ json: {
    guid: key,
    publishedAt: r.publishedAt || '',
    podcastTitle: r.podcastTitle || '',
    episodeTitle: r.episodeTitle || '',
    episodeNumber: r.episodeNumber ?? '',
    durationMinutes: r.durationSeconds ? Math.round(r.durationSeconds / 60) : '',
    wordCount: r.wordCount ?? '',
    speakers: Array.isArray(r.speakers) ? r.speakers.join(', ') : '',
    language: r.language || '',
    transcriptUrl: r.transcriptUrl || '',
    audioUrl: r.audioUrl || '',
    feedUrl: r.feedUrl || '',
    textTruncated: text.length > CELL_LIMIT,
    text: text.slice(0, CELL_LIMIT),
    savedAt: now,
  } });
}
// No new transcripts -> return nothing, so the workflow ends here without writing.
return out;
